let state=null, ui={page:'home',subject:null,grade:null,area:null,mathSkill:'auto',difficulty:'auto',qtype:'multiple_choice',question:null,selected:null,cdf:null,cid:null,corrected:false,hint:false,started:0,learningArea:null,programLang:'matematica_computacional',programLesson:0,exam:null,examReview:null,focus:false,search:'',searchOpen:false,essayPrompt:null,essayStarted:null};
