// ---------- compact answered bitset ----------
const bitCache=new WeakMap();
function bitBytes(stats){ if(bitCache.has(stats))return bitCache.get(stats); const n=Math.ceil((MANIFEST?.storageQuestions||MANIFEST?.totalQuestions||40000)/8), b=new Uint8Array(n); if(stats.answeredBits){try{const raw=atob(stats.answeredBits);for(let i=0;i<raw.length&&i<n;i++)b[i]=raw.charCodeAt(i)}catch{}} bitCache.set(stats,b); return b }
function answeredHas(stats,n){const b=bitBytes(stats);return !!(b[n>>3]&(1<<(n&7)))}
function answeredAdd(stats,n){const b=bitBytes(stats);b[n>>3]|=1<<(n&7)}
function flushBits(stats){const b=bitBytes(stats);let out='';for(let i=0;i<b.length;i+=8192)out+=String.fromCharCode(...b.subarray(i,i+8192));stats.answeredBits=btoa(out)}

// ---------- defaults ----------
function blankStats(){return {questions:0,correct:0,masteredCorrect:0,knowledge:0,confidence:0,speed:0,mastery:0,timeMs:0,cdf:{C:0,D:0,F:0},cid:{Conteudo:0,Interpretacao:0,Distracao:0},answeredBits:'',answeredCustom:[],answeredRoots:[],answeredPatterns:[],recentIds:[],recentRoots:[],recentPatterns:[],recentPrompts:[],recentAnswers:[],recentCorrectIndexes:[],topic:{},skill:{},errors:[],history:[]}}
