function normalize(){const d=defaults();if(!state||typeof state!=='object')state=d;if(!Array.isArray(state.users))state=d.users;for(const fixed of d.users){if(!state.users.some(u=>u.id===fixed.id))state.users.push(fixed)};for(const k of ['stats','topicDifficulty','prereqDone','favorites','notes','formulas','scratch','programDone','essays','examHistory','reviewQueue','sessionDrafts','routine'])state[k]=state[k]||{};state.customQuestions=Array.isArray(state.customQuestions)?state.customQuestions:[];state.officialQuestions=Array.isArray(state.officialQuestions)?state.officialQuestions:[];state.manualQueue=Array.isArray(state.manualQueue)?state.manualQueue:[];state.audit=Array.isArray(state.audit)?state.audit:[];state.settings=state.settings||{theme:'light',fontScale:1};for(const u of state.users){state.stats[u.id]=state.stats[u.id]||blankStats();if(typeof state.stats[u.id].answeredBits!=='string')state.stats[u.id].answeredBits='';if(!Array.isArray(state.stats[u.id].answeredCustom))state.stats[u.id].answeredCustom=[];for(const k of ['answeredCustom','answeredRoots','answeredPatterns','recentIds','recentRoots','recentPatterns','recentPrompts','recentAnswers','recentCorrectIndexes','errors','history'])if(!Array.isArray(state.stats[u.id][k]))state.stats[u.id][k]=[];state.stats[u.id].topic=state.stats[u.id].topic||{};state.stats[u.id].skill=state.stats[u.id].skill||{};hydrateAntiRepeat(state.stats[u.id]);state.topicDifficulty[u.id]=state.topicDifficulty[u.id]||{};state.prereqDone[u.id]=state.prereqDone[u.id]||{};state.favorites[u.id]=state.favorites[u.id]||[];state.notes[u.id]=state.notes[u.id]||{};state.formulas[u.id]=state.formulas[u.id]||[];state.scratch[u.id]=state.scratch[u.id]||{};state.programDone[u.id]=state.programDone[u.id]||[];state.essays[u.id]=state.essays[u.id]||[];state.examHistory[u.id]=state.examHistory[u.id]||[];state.reviewQueue[u.id]=state.reviewQueue[u.id]||[];state.routine[u.id]=state.routine[u.id]||{enabled:false,weeklyGoal:100,items:[]}}}
function loadState(){try{return JSON.parse(localStorage.getItem(STORE)||'null')||defaults()}catch{return defaults()}}
function localSave(){for(const s of Object.values(state.stats||{}))flushBits(s);localStorage.setItem(STORE,JSON.stringify(state));cloudSaveSoon()}
function audit(action,detail=''){const u=me();state.audit.push({at:new Date().toISOString(),user:u?.username||'sistema',action,detail});state.audit=state.audit.slice(-1500);localSave()}
function me(){return state.users.find(u=>u.id===state.currentUser)}
function targetStudent(){const m=me();if(m?.role==='student')return m;return state.users.find(u=>u.role==='student')||m}
function stats(uid=targetStudent()?.id){if(!state.stats[uid])state.stats[uid]=blankStats();return state.stats[uid]}
function gradeName(g){return Number(g)<=9?`${g}º ano`:`${Number(g)-9}º ano EM`}
function pct(x){return Math.max(0,Math.min(100,Math.round(Number(x)||0)))}
function recalc(s){s.knowledge=s.questions?Math.round(s.masteredCorrect/s.questions*100):0;const n=s.cdf.C+s.cdf.D+s.cdf.F;s.confidence=n?Math.round((s.cdf.C*100+s.cdf.D*60+s.cdf.F*20)/n):0;const avg=s.questions?s.timeMs/s.questions:0;s.speed=s.questions?Math.max(0,Math.min(100,Math.round(100-(avg/1000-35)*.7))):0;s.mastery=Math.round(s.knowledge*.55+s.confidence*.25+s.speed*.20)}
function keyTopic(q){return `${q.subject}|${q.grade}|${q.area}`}
function qById(id){return QMAP.get(id)||state.customQuestions.find(q=>q.id===id)||state.officialQuestions.find(q=>q.id===id)}
