function loginView(){return `<div class="login"><div class="login-card simple-login"><section class="login-hero"><div class="login-symbol">🎓</div><h1>AEDS</h1><p><b>A Evolução do Saber</b></p><p class="login-simple-copy">Um lugar para aprender, praticar e melhorar.</p><div class="login-icon-row" aria-hidden="true"><span>📘</span><span>🎯</span><span>🔁</span><span>📝</span></div></section><section class="login-form"><h2>Entrar</h2><div class="field"><label>${CLOUD.enabled?'E-mail':'Usuário'}</label><input id="loginUser" type="${CLOUD.enabled?'email':'text'}" autocomplete="username" placeholder="${CLOUD.enabled?'seuemail@exemplo.com':''}"></div><div class="field"><label>Senha</label><input id="loginPass" type="password" autocomplete="current-password"></div><button id="loginBtn" class="btn btn-primary btn-big" style="width:100%">Entrar →</button><div id="loginErr" class="danger hidden"></div>${CLOUD.enabled?'':`<div class="notice"><b>Teste local:</b> admin / 1234 &nbsp;·&nbsp; aluno / 1234</div>`}</section></div></div>`}
const NAV=[['home','🏠','Início'],['learn','📘','Aprender'],['train','🎯','Treinar'],['exam','📝','Provas'],['review','🔁','Revisar'],['essay','✍️','Redação'],['performance','📊','Progresso'],['favorites','⭐','Favoritos'],['formulas','🧮','Fórmulas'],['program','💻','Programação'],['science','🔬','Ciência'],['routine','🗓️','Rotina'],['sources','🔎','Fontes'],['official','🏛️','Banco oficial'],['settings','⚙️','Configurações']];
function sidebar(){const m=me(),items=m.role==='admin'?[['admin','🛠️','Admin'],...NAV]:NAV,primaryKeys=['home','learn','train','exam'],primary=items.filter(x=>primaryKeys.includes(x[0])),more=items.filter(x=>!primaryKeys.includes(x[0])),moreActive=more.some(x=>x[0]===ui.page),starter=items.filter(x=>primaryKeys.includes(x[0])),tools=items.filter(x=>!primaryKeys.includes(x[0]));return `<aside class="sidebar"><div class="brand"><div class="brand-mark">A</div><div><h2>AEDS</h2><div class="muted tiny">A Evolução do Saber · V8.27</div></div></div><div class="desktop-nav"><div class="nav-section">Começar</div>${starter.map(x=>`<button class="nav nav-visual ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<div class="nav-section">Mais</div>${tools.map(x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<div class="nav-section">Conta</div><button class="nav" id="logout"><span class="ico">🚪</span><span class="label">Sair</span></button></div><div class="mobile-nav">${primary.map(x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<details class="mobile-more"><summary class="nav ${moreActive?'active':''}"><span class="ico">☰</span><span class="label">Mais</span></summary><div class="mobile-more-sheet"><div class="mobile-more-head"><div><b>Escolha pela figura</b><div class="tiny muted">Toque em uma opção</div></div><button type="button" class="mobile-more-close" id="mobileMoreClose" aria-label="Fechar menu">×</button></div><div class="mobile-more-grid">${more.map(x=>`<button class="mobile-more-item ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span>${x[2]}</span></button>`).join('')}<button class="mobile-more-item danger-link" id="mobileLogout"><span class="ico">🚪</span><span>Sair</span></button></div></div></details></div></aside>`}
function shell(body){const m=me(),pm=PAGE_VISUAL[ui.page]||PAGE_VISUAL.home;return `<div class="shell">${sidebar()}<main class="main"><header class="topbar"><div class="page-identity" title="${pm.label}"><span>${pm.icon}</span><b>${pm.label}</b></div><div class="searchbox"><input id="globalSearch" value="${esc(ui.search)}" placeholder="🔎 Procurar..."><div id="searchResults" class="search-results ${ui.searchOpen?'':'hidden'}"></div></div><div class="top-actions"><button id="speakPage" class="btn btn-listen no-print" title="Ouvir esta tela" aria-label="Ouvir esta tela">🔊 <span>Ouvir</span></button><button id="focusBtn" class="btn btn-ghost no-print" title="Modo foco">◎ <span>Foco</span></button><div class="user-chip"><div class="avatar">${esc(m.name[0])}</div><div class="user-text"><b class="small">${esc(m.name)}</b><div class="tiny muted">${m.role==='admin'?'Administrador':gradeName(m.grade)}</div></div></div></div></header><section class="content">${body}<div class="footer">AEDS — A Evolução do Saber · V8.27 · ${CLOUD.enabled?'nuvem ativa':'modo local'}</div></section></main></div>`}
function metric(label,value,sub=''){return `<div class="card"><div class="metric-label">${label}</div><div class="metric">${value}</div><div class="muted small">${sub}</div></div>`}
function availableSubjects(u=targetStudent()){const all=Object.keys(MANIFEST.subjects);if(me()?.role==='admin')return all;if(!u)return[];if(!Array.isArray(u.unlockedSubjects))return all;return all.filter(s=>u.unlockedSubjects.includes(s))}
function availableGrades(subject,u=targetStudent()){const all=Object.keys(MANIFEST.subjects[subject]?.grades||{}).map(Number).sort((a,b)=>a-b);if(me()?.role==='admin')return all;if(!u)return[];const allowed=Array.isArray(u.unlockedGrades)?u.unlockedGrades:[u.grade];return all.filter(g=>allowed.includes(g))}
function areasFor(subject,grade){return Object.keys(MANIFEST.subjects[subject]?.grades?.[String(grade)]||{})}

// ---------- home ----------
function adminHome(){const students=state.users.filter(u=>u.role==='student'),pending=state.manualQueue.filter(x=>x.status==='pending').length;return `<div class="page-head"><div><h1>Início</h1><div class="muted">Visão geral da AEDS — A Evolução do Saber para o administrador.</div></div><div class="seg"><button class="btn btn-primary" data-page="admin">Abrir painel Admin</button><button class="btn btn-ghost" data-page="train">Testar treinamento</button></div></div><div class="grid g4">${metric('Alunos',students.length,'contas de estudante')}${metric('Banco local',MANIFEST.totalQuestions.toLocaleString('pt-BR'),'conteúdo atual do site')}${metric('Correções pendentes',pending,'discursivas e redações')}${metric('Nuvem',CLOUD.enabled?'Ativa':'Local',CLOUD.enabled?'Supabase conectado':'sem sincronização')}</div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>Próximo passo</h3>${students.length?`<p>Você já possui <b>${students.length}</b> aluno(s). Abra o painel Admin para liberar ou remover matérias, séries e provas.</p><button class="btn btn-primary" data-page="admin">Configurar alunos</button>`:`<p>Ainda não existe aluno cadastrado. Por isso não aparecem controles de matérias e séries no painel.</p><div class="notice">Crie primeiro uma conta em <b>Supabase → Authentication → Users → Add user → Create new user</b>. Depois volte à AEDS e use <b>Recarregar alunos</b>.</div>`}</div><div class="card"><h3>Teste do conteúdo</h3><p>Como administrador, você pode abrir Aprendizado e Treinamento mesmo sem aluno cadastrado.</p><div class="seg"><button class="btn btn-soft" data-page="learn">Abrir Aprendizado</button><button class="btn btn-soft" data-page="train">Abrir Treinamento</button></div></div></div>`}
function home(){const m=me();if(m.role==='admin')return adminHome();const s=stats(),first=esc((m.name||'Aluno').split(/\s+/)[0]),goal=state.routine[m.id]?.weeklyGoal||100;return `<div class="student-home"><section class="welcome-hero"><div><div class="eyebrow">AEDS</div><h1>Oi, ${first}! 👋</h1><p>Escolha uma figura para começar.</p></div><button class="listen-hero" id="speakHome" aria-label="Ouvir as opções"><span>🔊</span><b>Ouvir</b></button></section><section class="home-main-actions" aria-label="Ações principais">${visualAction('learn','📘','Aprender','Ver uma explicação','blue')}${visualAction('train','🎯','Treinar','Resolver uma questão','red')}${visualAction('review','🔁','Revisar','Tentar de novo','green')}${visualAction('exam','📝','Prova','Fazer uma prova','purple')}</section><div class="section-label">Outras coisas</div><section class="home-secondary-actions">${visualAction('essay','✍️','Redação','Escrever','orange')}${visualAction('performance','📊','Progresso','Ver como estou','blue')}${visualAction('favorites','⭐','Favoritos','O que guardei','yellow')}${visualAction('program','💻','Programação','Aprender código','purple')}</section><section class="progress-strip"><div><span class="progress-face">🌱</span><div><small>Domínio</small><b>${pct(s.mastery)}%</b></div></div><div><span class="progress-face">✅</span><div><small>Feitas</small><b>${s.questions.toLocaleString('pt-BR')}</b></div></div><div><span class="progress-face">🎯</span><div><small>Meta</small><b>${goal}</b></div></div></section></div>`}

// ---------- learning ----------
function learnView(){const subjects=availableSubjects();if(!subjects.length)return `<div class="visual-page-head"><span class="page-big-icon">📘</span><div><h1>Aprender</h1><p>Nenhuma matéria foi liberada.</p></div></div><div class="notice">Peça ao administrador para liberar pelo menos uma matéria.</div>`;if(!ui.subject||!subjects.includes(ui.subject))ui.subject=subjects[0];const grades=availableGrades(ui.subject);if(!grades.length)return `<div class="visual-page-head"><span class="page-big-icon">📘</span><div><h1>Aprender</h1><p>Escolha uma matéria.</p></div></div><div class="subject-picker">${subjects.map(s=>`<button class="subject-choice ${ui.subject===s?'active':''}" data-subject="${esc(s)}"><span>${subjectIcon(s)}</span><b>${esc(s)}</b></button>`).join('')}</div><div class="notice">Nenhuma série foi liberada nesta matéria.</div>`;if(!grades.includes(ui.grade))ui.grade=grades[0];const areas=areasFor(ui.subject,ui.grade);if(ui.learningArea&&!areas.includes(ui.learningArea))ui.learningArea=null;if(ui.learningArea)return learningArticle(ui.subject,ui.grade,ui.learningArea);const roadmap=ui.subject==='Matemática'?mathRoadmapHtml(ui.grade):ui.subject==='Português'?portRoadmapHtml(ui.grade):focusRoadmapHtml(ui.subject,ui.grade);return `<div class="visual-page-head"><span class="page-big-icon">📘</span><div><h1>Aprender</h1><p>1. Escolha a matéria &nbsp; 2. Escolha a série &nbsp; 3. Toque no assunto.</p></div></div><div class="section-label">1 · Matéria</div><div class="subject-picker">${subjects.map(s=>`<button class="subject-choice ${ui.subject===s?'active':''}" data-subject="${esc(s)}" aria-label="${esc(s)}"><span>${subjectIcon(s)}</span><b>${esc(s)}</b></button>`).join('')}</div><div class="section-label">2 · Série</div><div class="grade-picker">${grades.map(g=>`<button class="grade-choice ${ui.grade===g?'active':''}" data-grade="${g}">${gradeName(g)}</button>`).join('')}</div><div class="section-label">3 · Assunto</div>${roadmap}<div class="area-grid">${areas.map(a=>{const done=!!state.prereqDone[targetStudent().id]?.[`${ui.subject}|${ui.grade}|${a}`],prev=PREREQ?.[ui.subject]?.[String(ui.grade)]?.[a],micro=ui.subject==='Matemática'?mathSkillsFor(ui.grade,a).length:ui.subject==='Português'?portSkillsFor(ui.grade,a).length:focusSkillsFor(ui.subject,ui.grade,a).length;return `<button class="area-card learnArea" data-area="${esc(a)}"><span class="area-card-icon">${subjectIcon(ui.subject)}</span><span class="area-card-copy"><b>${esc(a)}</b><small>${micro?`${micro} aprofundamentos`:(prev?`Depois de ${esc(prev)}`:'Comece aqui')}</small></span><span class="area-card-status">${done?'✓':'›'}</span></button>`}).join('')}</div>`}

function learningArticle(subject,grade,area){const u=targetStudent(),key=`${subject}|${grade}|${area}`,done=!!state.prereqDone[u.id][key],prev=PREREQ?.[subject]?.[String(grade)]?.[area],d=LEARNING_BY_GRADE?.[subject]?.[String(grade)]?.[area]||LEARNING?.[subject]?.[area];const samples=BANK.filter(q=>q.subject===subject&&q.grade===grade&&q.area===area).slice(0,3);const desc=d?.description||`Esta área desenvolve ${area} em ${subject}. O objetivo é entender o conceito, reconhecer quando ele se aplica e justificar a resposta em situações diferentes.`;const steps=d?.steps||['Leia a situação e identifique exatamente o que é pedido.','Localize dados, evidências e palavras-chave.','Escolha o conceito ou procedimento adequado.','Resolva uma etapa de cada vez.','Confira se a conclusão responde ao comando.'];const example=d?.example||samples[0]?.explanation||`Use uma questão de ${area}, resolva em etapas e explique por que cada alternativa incorreta não serve.`;const errors=d?.errors||['Responder antes de identificar exatamente o que a questão pede.','Memorizar uma regra sem verificar se ela se aplica ao contexto.','Ignorar unidades, palavras-chave, exceções ou sinais importantes.'];const summary=d?.summary||`Em ${area}, o mais importante é reconhecer o tipo de problema, aplicar o conceito correto e conferir o significado da resposta.`;const refs=d?.references||samples.flatMap(q=>q.references||[]).slice(0,6);const detail=subject==='Matemática'?mathAreaDetailHtml(grade,area):subject==='Português'?portAreaDetailHtml(grade,area):focusAreaDetailHtml(subject,grade,area);return `<div class="page-head"><div><button id="backLearn" class="btn btn-ghost">← Áreas</button><h1 style="margin-top:12px">${esc(area)}</h1><div class="muted">${subject} · ${gradeName(grade)}</div></div><div class="seg"><button id="togglePrereq" class="btn ${done?'btn-ok':'btn-soft'}">${done?'Concluído ✓':'Marcar como estudado'}</button><button id="trainThisArea" class="btn btn-primary">Treinar</button></div></div><article class="card article"><span class="pill">${prev?`Antes: ${esc(prev)}`:'Trilha desta série'}</span>${detail}<h2>O que é e por que importa</h2><p>${esc(desc)}</p><h3>Como pensar</h3><div class="steps">${steps.map(x=>`<div class="step">${esc(x)}</div>`).join('')}</div><h3>Exemplo de método</h3><div class="notice">${esc(example)}</div>${learningSectionsHtml(d)}<h3>Erros comuns</h3><ul>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Como estudar melhor este conteúdo</h3><p>Não memorize apenas a resposta final. Reconstrua a ideia central, explique por que a relação escolhida faz sentido e confronte o resultado com o contexto. No nível ENEM, texto, gráfico, imagem e situação real podem carregar parte do raciocínio necessário.</p><h3>Guarde esta ideia</h3><p>${esc(summary)}</p><h3>Fontes utilizadas como referência</h3>${refsHtml(refs)}</article>`}

// ---------- question selection ----------
function topicDifficulty(u,key){return state.topicDifficulty[u.id]?.[key]||'auto'}
function adaptiveDifficulty(s,key){const t=s.topic[key];if(!t||t.done<5)return 'fácil';const rate=t.correct/t.done;return rate>0.8?'difícil':rate>0.55?'médio':'fácil'}
function candidateBank(){return BANK.filter(q=>q.active!==false).concat(state.customQuestions).concat(state.officialQuestions)}
function selectQuestion({subject,grade,area,difficulty='',questionType='multiple_choice',sameSkill=null,skill=null,excludeId=null,excludeRoot=null}={}){const u=targetStudent(),s=stats(u.id),recentAns=new Set((s.recentAnswers||[]).slice(-8)),lastIndexes=(s.recentCorrectIndexes||[]).slice(-2);let p=candidateBank().filter(q=>(!subject||q.subject===subject)&&(!grade||Number(q.grade)===Number(grade))&&(!area||q.area===area)&&(!sameSkill||q.skill===sameSkill)&&(!skill||q.skill===skill)&&(!questionType||q.questionType===questionType)&&q.id!==excludeId&&q.rootFamily!==excludeRoot&&isQuestionFresh(q,s));if(difficulty)p=p.filter(q=>q.difficulty===difficulty);if(!p.length)return null;const key=area?`${subject}|${grade}|${area}`:null;if(key){const ts=s.topic[key];if(ts&&ts.errors>2){const ranked=[['conteúdo',ts.content||0],['interpretação',ts.interpretation||0],['atenção',ts.distraction||0]].sort((x,y)=>y[1]-x[1]);const target=ranked[0][1]>0?ranked[0][0]:null;if(target){const typed=p.filter(q=>q.type===target);if(typed.length)p=typed}}}let a=p.filter(q=>!q.correctText||!recentAns.has(q.correctText));if(a.length)p=a;a=p.filter(q=>!Number.isInteger(q.correctIndex)||!lastIndexes.length||!lastIndexes.every(i=>i===q.correctIndex));if(a.length)p=a;if(['Matemática','Português'].includes(subject)&&!skill&&!sameSkill){const groups=collectionsBy(p,q=>q.skill||q.area),ranked=Object.entries(groups).map(([sk,arr])=>{const st=s.skill[`${subject}|${grade}|${area}|${sk}`]||{done:0,correct:0,errors:0};const rate=st.done?st.correct/st.done:0;return {arr,score:(st.done===0?80:0)+(st.errors||0)*10+(1-rate)*50-Math.min(st.done,10)}}).sort((x,y)=>y.score-x.score);if(ranked.length)p=ranked.slice(0,Math.min(4,ranked.length))[Math.floor(Math.random()*Math.min(4,ranked.length))].arr}return p[Math.floor(Math.random()*p.length)]}
function setupTrain(){const subjects=availableSubjects();if(!subjects.length){ui.subject=null;ui.grade=null;ui.area=null;ui.mathSkill='auto';return false}if(!ui.subject||!subjects.includes(ui.subject))ui.subject=subjects[0];const grades=availableGrades(ui.subject);if(!grades.length){ui.grade=null;ui.area=null;ui.mathSkill='auto';return false}if(!grades.includes(ui.grade))ui.grade=grades[0];const areas=areasFor(ui.subject,ui.grade);if(!areas.length){ui.area=null;ui.mathSkill='auto';return false}if(!ui.area||!areas.includes(ui.area))ui.area=areas[0];if(['Matemática','Português'].includes(ui.subject)){const skills=ui.subject==='Matemática'?mathSkillsFor(ui.grade,ui.area):portSkillsFor(ui.grade,ui.area);if(ui.mathSkill!=='auto'&&!skills.includes(ui.mathSkill))ui.mathSkill='auto'}else ui.mathSkill='auto';return true}
async function nextTrainingQuestion(){if(!setupTrain())return alert('Nenhuma matéria/série/assunto está disponível para esta conta.');let diff=ui.difficulty;if(diff==='auto')diff=adaptiveDifficulty(stats(),`${ui.subject}|${ui.grade}|${ui.area}`);const wantedSkill=['Matemática','Português'].includes(ui.subject)&&ui.mathSkill!=='auto'?ui.mathSkill:null;let q=null;if(CLOUD.enabled&&cloudSession&&ui.qtype==='multiple_choice'&&!['Matemática','Português'].includes(ui.subject)){const key=`${ui.subject}|${ui.grade}|${ui.area}|${wantedSkill||'auto'}|${diff}`;try{if(cloudTrainingKey!==key||!cloudTrainingQueue.length){cloudTrainingKey=key;cloudTrainingQueue=await cloudTrainingBatch({subject:ui.subject,grade:ui.grade,area:ui.area,difficulty:diff==='todas'?'':diff})}while(cloudTrainingQueue.length&&!q){const candidate=cloudTrainingQueue.shift();if((!wantedSkill||candidate.skill===wantedSkill)&&isQuestionFresh(candidate,stats()))q=candidate}}catch(e){console.warn('lote online',e)}}if(!q)q=selectQuestion({subject:ui.subject,grade:ui.grade,area:ui.area,skill:wantedSkill,difficulty:diff==='todas'?'':diff,questionType:ui.qtype});if(!q&&diff!=='todas')q=selectQuestion({subject:ui.subject,grade:ui.grade,area:ui.area,skill:wantedSkill,difficulty:'',questionType:ui.qtype});ui.question=q;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Date.now();if(!q){state.sessionDrafts[targetStudent().id]=null;localSave();render();return alert(`Não há outra questão realmente inédita para ${wantedSkill||ui.area}. A AEDS bloqueou IDs, famílias e padrões que você já viu. Escolha outra habilidade ou área.`)}saveSessionDraft();render()}
function renderMedia(m){if(!m)return'';if(m.type==='table')return `<div class="media-box"><table class="media-table"><thead><tr>${m.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${m.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;if(m.type==='bars'){const max=Math.max(...m.values);return `<div class="media-box"><b>${esc(m.title||'Gráfico')}</b><div class="bars">${m.values.map((v,i)=>`<div class="barcol" style="height:${Math.max(8,v/max*130)}px"><span>${v}</span><em>${esc(m.labels[i])}</em></div>`).join('')}</div></div>`}if(m.type==='image'&&m.src)return `<div class="media-box"><b>${esc(m.title||'Imagem de apoio')}</b><img src="${esc(m.src)}" alt="${esc(m.alt||m.title||'Imagem da questão')}" style="display:block;max-width:100%;max-height:360px;margin:10px auto;border-radius:10px"></div>`;if(m.type==='svg'&&m.svg)return `<div class="media-box"><b>${esc(m.title||'Figura de apoio')}</b><div style="max-width:420px;margin:auto">${m.svg}</div></div>`;return''}
function trainView(){const ready=setupTrain(),subjects=availableSubjects();if(!ready)return `<div class="visual-page-head"><span class="page-big-icon">🎯</span><div><h1>Treinar</h1><p>Nenhum conteúdo disponível.</p></div></div><div class="notice">${me()?.role==='admin'?'Atualize a página ou confira o banco.':'Peça ao administrador para liberar uma matéria e uma série.'}</div>`;const grades=availableGrades(ui.subject),areas=areasFor(ui.subject,ui.grade),rebuilt=['Matemática','Português'].includes(ui.subject),skills=ui.subject==='Matemática'?mathSkillsFor(ui.grade,ui.area):ui.subject==='Português'?portSkillsFor(ui.grade,ui.area):[];const key=`${ui.subject}|${ui.grade}|${ui.area}`,td=topicDifficulty(targetStudent(),key),recommended=ui.subject==='Matemática'?recommendMathTarget(ui.grade,ui.area):ui.subject==='Português'?recommendPortTarget(ui.grade,ui.area):null;const filters=`<details class="advanced-filters no-print"><summary><span>⚙️</span><b>Escolher o treino</b><small>matéria, série e dificuldade</small></summary><div class="advanced-body"><div class="toolbar"><div class="field"><label>Matéria</label><select id="trainSubject">${subjects.map(s=>`<option ${s===ui.subject?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Série</label><select id="trainGrade">${grades.map(g=>`<option value="${g}" ${g===ui.grade?'selected':''}>${gradeName(g)}</option>`).join('')}</select></div><div class="field"><label>${rebuilt?'Unidade':'Assunto'}</label><select id="trainArea">${areas.map(a=>`<option ${a===ui.area?'selected':''}>${esc(a)}</option>`).join('')}</select></div>${rebuilt?`<div class="field skill-filter"><label>Habilidade</label><select id="trainMathSkill"><option value="auto" ${ui.mathSkill==='auto'?'selected':''}>Automática</option>${skills.map(sk=>`<option value="${esc(sk)}" ${ui.mathSkill===sk?'selected':''}>${esc(sk)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Dificuldade</label><select id="trainDifficulty"><option value="auto" ${ui.difficulty==='auto'?'selected':''}>Automática</option>${['fácil','médio','difícil'].map(d=>`<option ${ui.difficulty===d?'selected':''}>${d}</option>`).join('')}<option value="todas" ${ui.difficulty==='todas'?'selected':''}>Todas</option></select></div><div class="field"><label>Tipo</label><select id="trainType"><option value="multiple_choice" ${ui.qtype==='multiple_choice'?'selected':''}>Alternativas</option><option value="discursive" ${ui.qtype==='discursive'?'selected':''}>Escrever resposta</option></select></div></div><button id="loadManualQ" class="btn btn-soft btn-big">Usar estas escolhas</button></div></details>`;const start=`<section class="start-training-card"><div class="start-training-icon">🎯</div><h2>Pronto para treinar?</h2><p><span>${subjectIcon(ui.subject)}</span> <b>${esc(ui.subject)}</b> · ${gradeName(ui.grade)}</p>${rebuilt?`<button id="subjectSmart" class="btn btn-primary mega-start">🎯 Começar</button><div class="smart-hint">A AEDS escolhe o melhor próximo passo${recommended?`: <b>${esc(recommended.skill)}</b>`:'.'}</div>`:`<button id="loadQ" class="btn btn-primary mega-start">🎯 Começar</button>`}</section>`;return `<div class="visual-page-head"><span class="page-big-icon">🎯</span><div><h1>Treinar</h1><p>Uma questão de cada vez. Sem distração.</p></div><div class="page-head-actions"><button id="focusTrain" class="btn btn-ghost">◎ Foco</button><button id="favCurrent" class="btn btn-ghost">⭐ Guardar</button></div></div>${me()?.role==='admin'?`<div class="admin-engine-note"><b>Motor 8.27:</b> bloqueio por ID, família, padrão estrutural e similaridade. Dificuldade atual: ${td==='auto'?adaptiveDifficulty(stats(),key):td}.</div>`:''}${ui.question?questionView(ui.question):start}${filters}`}

function questionView(q,{exam=false,review=false}={}){if(q.questionType==='discursive')return discursiveQuestionView(q,{review});const calc=q.calculatorAllowed&&!review;return `<div class="question-layout"><div class="card question-card"><div class="qmeta"><span class="tag">${esc(q.subject)}</span><span class="tag">${gradeName(q.grade)}</span><span class="tag">${esc(q.area)}</span><span class="tag">${esc(q.skill)}</span><span class="tag">${esc(q.difficulty)}</span><span class="tag">${esc(q.type)}</span></div><div class="qtext">${esc(q.prompt)}</div>${renderMedia(q.media)}${!exam?`<button id="hintBtn" class="btn btn-soft no-print">Dica</button><div id="hintBox" class="notice ${ui.hint?'':'hidden'}"><b>Dica:</b> ${esc(q.hint)}</div>`:''}<div id="optionsBox">${q.options.map((o,i)=>optionRow(q,o,i)).join('')}</div><div style="margin-top:14px"><b>CDF — antes de confirmar</b><div class="seg" style="margin-top:7px">${[['C','Certeza'],['D','Dúvida'],['F','Falha/chute']].map(x=>`<button class="choice cdf ${ui.cdf===x[0]?'selected':''}" data-v="${x[0]}" ${ui.corrected?'disabled':''}>${x[1]}</button>`).join('')}</div></div>${ui.corrected?feedbackBlock(q):''}<div class="seg" style="justify-content:flex-end;margin-top:14px">${ui.corrected?`<button id="nextQ" class="btn btn-primary">Próxima questão</button>`:`<button id="confirmQ" class="btn btn-primary" ${ui.selected===null||!ui.cdf?'disabled':''}>Confirmar</button>`}</div></div><aside class="side-tools no-print"><div class="card"><h3>Rascunho</h3><textarea id="scratch" class="scratch" placeholder="Faça contas, anote palavras-chave...">${esc(state.scratch[targetStudent().id]?.[q.id]||'')}</textarea><div class="muted tiny">Salvo automaticamente.</div></div>${calc?calculatorCard():''}<div class="card"><h3>Atalhos</h3><div class="tiny muted">1–6: alternativas · C/D/F: confiança · H: dica · N: próxima · R: rascunho</div></div></aside></div>`}
function optionExplanation(q,i){if(q.optionExplanations?.[i])return q.optionExplanations[i];if(i===q.correctIndex)return `Correta. ${q.explanation} Essa alternativa atende ao que o enunciado pede e é compatível com a habilidade ${q.skill}.`;return `Incorreta. “${q.options[i]}” não satisfaz o mesmo raciocínio. Compare-a com a resposta correta “${q.correctText}”, volte ao comando e confira qual dado, conceito ou relação foi ignorado.`}
function explanationSteps(q){if(q.explanationSteps?.length)return q.explanationSteps;return [`Leia o comando inteiro e diga com suas palavras o que precisa ser encontrado.`,`Identifique a habilidade central: ${q.skill}.`,`Aplique a ideia correta: ${q.explanation}`,`Confira se “${q.correctText}” responde exatamente ao comando, incluindo unidade, contexto, data, sinal ou condição quando existirem.`]}
function optionRow(q,o,i){const selected=ui.selected===i,corrected=ui.corrected,cls=corrected?(i===q.correctIndex?'correct':(selected?'wrong':'')):(selected?'selected-before':'');return `<div class="option ${cls}" data-opt="${i}"><div class="option-main"><input type="radio" name="answer" value="${i}" ${selected?'checked':''} ${corrected?'disabled':''}><span class="letter">${LETTERS[i]})</span><span>${esc(o)}</span>${corrected?`<button class="explain-arrow" data-explain="${i}" title="Abrir/fechar explicação">↓</button>`:'<span></span>'}</div>${corrected?`<div class="opt-detail hidden" id="detail-${i}">${esc(optionExplanation(q,i))}</div>`:''}</div>`}
function detailedExplanation(q){return `<div class="card" style="margin-top:12px"><h3>Explicação detalhada</h3><div class="steps">${explanationSteps(q).map(x=>`<div class="step">${esc(String(x).replace(/^\d+\.\s*/,''))}</div>`).join('')}</div><p><b>Resposta:</b> ${esc(q.correctText)}</p><p>${esc(q.explanation)}</p><p><b>Como conferir:</b> tente explicar por que a alternativa correta funciona sem citar apenas a letra. Depois abra as setas das opções incorretas e identifique qual parte do raciocínio falha.</p><h4>Créditos e fontes</h4>${refsHtml(q.references)}</div>`}
function feedbackBlock(q){const right=ui.selected===q.correctIndex;return `<div class="feedback"><div class="${right?'success':'danger'}"><b>${right?'Correta.':'Incorreta.'}</b> ${esc(q.explanation)}</div>${!right?`<div class="warning"><b>CID — qual foi o principal motivo?</b><div class="seg" style="margin-top:7px">${[['Conteudo','Conteúdo'],['Interpretacao','Interpretação'],['Distracao','Distração']].map(x=>`<button class="choice cid ${ui.cid===x[0]?'selected':''}" data-v="${x[0]}">${x[1]}</button>`).join('')}<span class="tiny muted">Só um CID fica salvo; trocar atualiza o registro.</span></div></div>`:''}${detailedExplanation(q)}</div>`}
function calculatorCard(){return `<div class="card"><h3>Calculadora permitida</h3><input id="calcDisplay" class="calc-display" value=""><div class="calc-grid" style="margin-top:7px">${['7','8','9','/','4','5','6','*','1','2','3','-','0','.','(',')','+','%','C','='].map(x=>`<button class="calcKey" data-k="${x}">${x}</button>`).join('')}</div></div>`}
function discursiveQuestionView(q,{review=false}={}){return `<div class="question-layout"><div class="card"><div class="qmeta"><span class="tag">Discursiva</span><span class="tag">${q.subject}</span><span class="tag">${q.area}</span></div><div class="qtext">${esc(q.prompt)}</div>${renderMedia(q.media)}<div class="field"><label>Sua resposta</label><textarea id="discAnswer" style="min-height:220px">${esc(state.sessionDrafts[targetStudent().id]?.discAnswer||'')}</textarea></div><div class="seg"><button id="submitDisc" class="btn btn-primary">Enviar para correção</button></div><div class="notice"><b>Rubrica:</b> identifique o problema, explique o conceito, aplique ao caso e conclua. A correção pode ser manual pelo administrador.</div>${detailedExplanation(q)}</div><aside class="side-tools"><div class="card"><h3>Rascunho</h3><textarea id="scratch" class="scratch">${esc(state.scratch[targetStudent().id]?.[q.id]||'')}</textarea></div></aside></div>`}
function saveSessionDraft(){const u=targetStudent();if(!u)return;state.sessionDrafts[u.id]={page:ui.page,questionId:ui.question?.id||null,selected:ui.selected,cdf:ui.cdf,exam:ui.exam?JSON.parse(JSON.stringify(ui.exam)):null,started:ui.started||Date.now(),at:Date.now()};localSave()}
function restoreSessionDraft(){const u=targetStudent();if(!u)return;const d=state.sessionDrafts?.[u.id];if(!d)return;if(d.page==='exam'&&d.exam&&Array.isArray(d.exam.questions)&&d.exam.questions.length){ui.exam=d.exam;ui.page='exam';return}if(d.page==='train'&&d.questionId){const q=qById(d.questionId);if(q){ui.page='train';ui.question=q;ui.subject=q.subject;ui.grade=Number(q.grade);ui.area=q.area;ui.selected=Number.isInteger(d.selected)?d.selected:null;ui.cdf=d.cdf||null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Number(d.started)||Date.now()}}}
function selectAnswer(i){if(ui.corrected)return;ui.selected=i;$$('.option').forEach((el,j)=>el.classList.toggle('selected-before',j===i));$$('input[name="answer"]').forEach(x=>x.checked=Number(x.value)===i);const b=$('#confirmQ');if(b)b.disabled=ui.selected===null||!ui.cdf;saveSessionDraft()}
function setCDF(v){if(ui.corrected)return;ui.cdf=v;$$('.cdf').forEach(b=>b.classList.toggle('selected',b.dataset.v===v));const c=$('#confirmQ');if(c)c.disabled=ui.selected===null||!ui.cdf;saveSessionDraft()}
async function confirmQuestion(){const q=ui.question,s=stats();if(!q||ui.corrected||ui.selected===null||!ui.cdf)return;const elapsed=Math.max(1,Date.now()-ui.started);let right=false;if(q.remote){try{const row=await cloudSubmitAnswer(q,ui.selected,ui.cdf,elapsed);q.correctIndex=LETTERS.indexOf(String(row.answer_correct||'').toUpperCase());q.correctText=q.correctIndex>=0?q.options[q.correctIndex]||row.answer_correct:row.answer_correct;q.explanation=row.answer_explanation||'';right=!!row.is_correct}catch(e){alert(`Não foi possível corrigir online: ${e.message}`);return}}else right=ui.selected===q.correctIndex;ui.corrected=true;s.questions++;s.timeMs+=elapsed;s.cdf[ui.cdf]++;s.correct+=right?1:0;if(right&&ui.cdf!=='F')s.masteredCorrect++;if(q.n!=null&&q.n>=0)answeredAdd(s,q.n);else if(!s.answeredCustom.includes(q.id))s.answeredCustom.push(q.id);s.recentIds.push(q.id);s.recentIds=s.recentIds.slice(-120);markQuestionSeen(s,q);const k=keyTopic(q),t=s.topic[k]||(s.topic[k]={done:0,correct:0,errors:0,interpretation:0,content:0,distraction:0});t.done++;if(right&&ui.cdf!=='F')t.correct++;else t.errors++;recordSkillResult(s,q,right,ui.cdf,elapsed);const rec={qid:q.id,at:new Date().toISOString(),selected:ui.selected,correct:q.correctIndex,cdf:ui.cdf,cid:null,right,ms:elapsed,subject:q.subject,grade:q.grade,area:q.area,skill:q.skill};s.history.push(rec);s.history=s.history.slice(-1600);if(!right)s.errors.push(rec);s.errors=s.errors.slice(-1600);recalc(s);state.sessionDrafts[targetStudent().id]=null;localSave();render()}
async function setCID(v){const s=stats(),rec=[...s.history].reverse().find(r=>r.qid===ui.question.id);if(!rec)return;if(ui.question?.remote){try{await cloudSetAnswerCID(ui.question,v)}catch(e){alert(`Não foi possível salvar o CID: ${e.message}`);return}}const field=v==='Conteudo'?'content':v==='Interpretacao'?'interpretation':'distraction';if(rec.cid){s.cid[rec.cid]=Math.max(0,s.cid[rec.cid]-1);const t=s.topic[keyTopic(ui.question)],sk=s.skill[keySkill(ui.question)],oldField=rec.cid==='Conteudo'?'content':rec.cid==='Interpretacao'?'interpretation':'distraction';if(t)t[oldField]=Math.max(0,(t[oldField]||0)-1);if(sk)sk[oldField]=Math.max(0,(sk[oldField]||0)-1)}rec.cid=v;s.cid[v]++;const t=s.topic[keyTopic(ui.question)],sk=ensureSkillStat(s,ui.question);if(t)t[field]=(t[field]||0)+1;sk[field]=(sk[field]||0)+1;ui.cid=v;localSave();$$('.cid').forEach(b=>b.classList.toggle('selected',b.dataset.v===v))}
// ---------- exams ----------
function newExam(day=1){const u=targetStudent(),stt=stats(u.id);if(!u.examsUnlocked)return alert('Provas ainda não foram liberadas para esta conta.');const pool=[];for(const q of BANK){if(q.active===false||q.questionType!=='multiple_choice'||!u.unlockedGrades.includes(Number(q.grade))||!availableSubjects(u).includes(q.subject)||!isQuestionFresh(q,stt))continue;pool.push(q)}if(!pool.length)return alert('Não há questões realmente inéditas disponíveis para montar esta prova. Revise as permissões ou avance para novos conteúdos.');const bySubject=collectionsBy(pool,q=>q.subject),selected=[],answers=new Set(),roots=new Set(),patterns=new Set(),indexes=[];const subjects=Object.keys(bySubject);if(!subjects.length)return alert('Não há matérias com questões disponíveis para esta prova.');let cursor=0,guard=0;while(selected.length<100&&guard<20000){guard++;const sub=subjects[cursor++%subjects.length],arr=bySubject[sub];if(!arr?.length)continue;const q=arr.splice(Math.floor(Math.random()*arr.length),1)[0],root=q.rootFamily||q.family,pat=promptPattern(q);if((root&&roots.has(root))||(pat&&patterns.has(pat))||(q.correctText&&answers.has(q.correctText))||(Number.isInteger(q.correctIndex)&&indexes.slice(-2).every(i=>i===q.correctIndex)&&indexes.length>=2))continue;if(selected.some(x=>promptSimilarity(x.prompt,q.prompt)>=.78))continue;if(root)roots.add(root);if(pat)patterns.add(pat);if(q.correctText)answers.add(q.correctText);if(Number.isInteger(q.correctIndex))indexes.push(q.correctIndex);selected.push(q)}if(!selected.length)return alert('As regras antirrepetição bloquearam todas as questões disponíveis para esta prova. Libere novos conteúdos ou amplie o banco antes de repetir modelos antigos.');ui.exam={id:`EX-${Date.now()}`,day,questions:selected.map(q=>q.id),index:0,answers:{},startedAt:Date.now(),limitMs:5*60*60*1000,finished:false};ui.page='exam';saveSessionDraft();localSave();render()}
function collectionsBy(arr,fn){const o={};for(const x of arr)(o[fn(x)]??=[]).push(x);return o}
function examView(){const e=ui.exam;if(!e)return `<div class="visual-page-head"><span class="page-big-icon">📝</span><div><h1>Provas</h1><p>Escolha um dia para começar.</p></div></div><div class="exam-day-grid"><button class="exam-day-card startExam" data-day="1"><span class="exam-day-icon">1️⃣</span><b>Dia 1</b><small>até 100 questões</small><span class="exam-go">Começar ›</span></button><button class="exam-day-card startExam" data-day="2"><span class="exam-day-icon">2️⃣</span><b>Dia 2</b><small>até 100 questões</small><span class="exam-go">Começar ›</span></button></div><div class="friendly-note"><span>🔁</span><div><b>Depois da prova</b><p>A AEDS separa o que você errou ou ficou em dúvida para revisar com outra questão.</p></div></div>`;if(e.finished)return examResultView(e);const q=qById(e.questions[e.index]);if(!q)return `<div class="danger">Questão da prova não encontrada.</div>`;const a=e.answers[q.id]||{selected:null,cdf:null};const elapsed=Date.now()-e.startedAt,left=Math.max(0,e.limitMs-elapsed);return `<div class="page-head"><div><h1>Prova · Dia ${e.day}</h1><div class="muted">Questão ${e.index+1}/${e.questions.length}</div></div><div class="timer" id="examTimer" data-left="${left}">${fmtTime(left)}</div></div><div class="card question-card"><div class="qmeta"><span class="tag">${q.subject}</span><span class="tag">${gradeName(q.grade)}</span><span class="tag">${q.area}</span><span class="tag">${q.difficulty}</span></div><div class="qtext">${esc(q.prompt)}</div>${renderMedia(q.media)}${q.options.map((o,i)=>`<label class="option" style="display:flex;gap:9px;padding:11px"><input name="examAnswer" type="radio" value="${i}" ${a.selected===i?'checked':''}><b>${LETTERS[i]})</b><span>${esc(o)}</span></label>`).join('')}<div><b>CDF</b><div class="seg" style="margin-top:7px">${[['C','Certeza'],['D','Dúvida'],['F','Falha/chute']].map(x=>`<button class="choice examCDF ${a.cdf===x[0]?'selected':''}" data-v="${x[0]}">${x[1]}</button>`).join('')}</div></div>${q.calculatorAllowed?calculatorCard():''}<div class="seg" style="justify-content:space-between;margin-top:14px"><button id="examPrev" class="btn btn-ghost" ${e.index===0?'disabled':''}>Anterior</button>${e.index===e.questions.length-1?`<button id="finishExam" class="btn btn-primary">Finalizar prova</button>`:`<button id="examNext" class="btn btn-primary">Próxima</button>`}</div></div>`}
function fmtTime(ms){const sec=Math.floor(ms/1000),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function storeExamAnswer(){if(!ui.exam)return;const q=qById(ui.exam.questions[ui.exam.index]);const sel=$('input[name="examAnswer"]:checked');const a=ui.exam.answers[q.id]||(ui.exam.answers[q.id]={selected:null,cdf:null,cid:null});if(sel)a.selected=Number(sel.value);saveSessionDraft();localSave()}
function finishExam(){const e=ui.exam,s=stats(),review=[];let right=0,answered=0;for(const id of e.questions){const q=qById(id),a=e.answers[id]||{};if(a.selected==null)continue;answered++;const isRight=a.selected===q.correctIndex,cdf=a.cdf||'F';s.questions++;s.cdf[cdf]++;s.correct+=isRight?1:0;if(isRight&&cdf!=='F'){s.masteredCorrect++;right++}if(q.n!=null&&q.n>=0)answeredAdd(s,q.n);else if(!s.answeredCustom.includes(q.id))s.answeredCustom.push(q.id);markQuestionSeen(s,q);const k=keyTopic(q),t=s.topic[k]||(s.topic[k]={done:0,correct:0,errors:0,interpretation:0,content:0,distraction:0});t.done++;if(isRight&&cdf!=='F')t.correct++;else t.errors++;recordSkillResult(s,q,isRight,cdf,0);const rec={qid:q.id,at:new Date().toISOString(),selected:a.selected,correct:q.correctIndex,cdf,cid:null,right:isRight,ms:0,subject:q.subject,grade:q.grade,area:q.area,skill:q.skill,examId:e.id};s.history.push(rec);if(!isRight)s.errors.push(rec);if(!isRight||cdf==='D'||cdf==='F')review.push({qid:q.id,reason:!isRight?'errada':cdf==='D'?'dúvida':'falha'})}s.timeMs+=Math.max(1,Date.now()-e.startedAt);s.history=s.history.slice(-1600);s.errors=s.errors.slice(-1600);recalc(s);e.finished=true;e.result={answered,right,total:e.questions.length,review};state.examHistory[targetStudent().id].push(JSON.parse(JSON.stringify(e)));state.examHistory[targetStudent().id]=state.examHistory[targetStudent().id].slice(-20);state.reviewQueue[targetStudent().id]=review;state.sessionDrafts[targetStudent().id]=null;localSave();render()}
function examResultView(e){const r=e.result;return `<div class="page-head"><div><h1>Resultado · Dia ${e.day}</h1><div class="muted">Correção completa e revisão das questões que precisam de atenção.</div></div><button id="closeExam" class="btn btn-ghost">Voltar</button></div><div class="grid g3">${metric('Respondidas',r.answered)}${metric('Domínio correto',r.right)}${metric('Para revisão',r.review.length,'erradas + dúvidas + falhas')}</div><div class="card" style="margin-top:14px"><h3>Modo revisão de prova</h3><p>A lista abaixo contém somente as questões que merecem revisão. Ao praticar, o sistema procura <b>outra questão da mesma habilidade</b>.</p><button id="startExamReview" class="btn btn-primary" ${r.review.length?'':'disabled'}>Revisar ${r.review.length} itens</button><div class="list" style="margin-top:10px">${r.review.slice(0,100).map(x=>{const q=qById(x.qid);return `<div class="item"><b>${q.subject} · ${q.area}</b> <span class="tag">${x.reason}</span><div class="small">${esc(q.prompt.slice(0,160))}</div></div>`}).join('')}</div></div>`}
function startExamReview(){const queue=state.reviewQueue[targetStudent().id]||[];ui.examReview={queue:[...queue],index:0};ui.page='review';render()}

// ---------- review ----------
function reviewView(){const s=stats(),queue=state.reviewQueue[targetStudent().id]||[];if(ui.examReview&&ui.examReview.queue.length){const item=ui.examReview.queue[ui.examReview.index];const old=qById(item.qid);if(!ui.question||ui.reviewSourceId!==old.id){ui.question=selectQuestion({subject:old.subject,grade:old.grade,area:old.area,sameSkill:old.skill,excludeId:old.id,excludeRoot:old.rootFamily,questionType:'multiple_choice'});ui.reviewSourceId=old.id;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.started=Date.now()}const nq=ui.question;return `<div class="page-head"><div><h1>Revisão de prova</h1><div class="muted">${ui.examReview.index+1}/${ui.examReview.queue.length} · ${item.reason}</div></div><button id="exitExamReview" class="btn btn-ghost">Sair</button></div><div class="card"><h3>Questão antiga — somente referência</h3><p>${esc(old.prompt)}</p><div class="muted">Ela não volta como exercício novo.</div></div><div style="margin-top:12px">${nq?questionView(nq,{review:true}):`<div class="warning">Não encontrei outra questão inédita da mesma habilidade. Revise a explicação antiga e o conteúdo de ${esc(old.skill)}.</div><div class="seg" style="justify-content:flex-end;margin-top:12px"><button id="skipReview" class="btn btn-primary">Próximo item da revisão</button></div>`}</div>`}return `<div class="visual-page-head"><span class="page-big-icon">🔁</span><div><h1>Revisar</h1><p>Veja o que merece outra tentativa.</p></div></div><div class="grid g4">${metric('Erros',s.errors.length)}${metric('Dúvidas',s.cdf.D)}${metric('Falhas/chutes',s.cdf.F)}${metric('Fila pós-prova',queue.length)}</div><div class="card" style="margin-top:14px"><h3>Caderno de erros</h3>${s.errors.length?`<div class="list">${s.errors.slice(-250).reverse().map(e=>{const q=qById(e.qid);return q?`<div class="item"><b>${q.subject} · ${q.area}</b> <span class="tag">CDF ${e.cdf}</span> <span class="tag">CID ${e.cid||'não marcado'}</span><div class="small">${esc(q.prompt.slice(0,180))}</div></div>`:''}).join('')}</div>`:`<div class="empty-friendly"><span>🌟</span><b>Nada para revisar agora</b><small>Continue treinando.</small></div>`}</div>`}

